import React, { useState } from 'react';
import axios from 'axios';  // Make sure to import axios

const AddExpense = ({ trip, expenses, setExpenses }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [paidBy, setPaidBy] = useState('');

  // Fetching the family heads (make sure it's not empty)
  const getFamilyHeads = () => {
    if (!trip || !trip.families) return [];
    return trip.families.map(family => ({
      name: family.head,
      label: `${family.head} (Head)`
    }));
  };

  const members = getFamilyHeads();

  const handleAddExpense = async () => {
    if (!description || !amount || !paidBy) return;

    const newExpense = {
      description,
      amount: parseFloat(amount),
      paidBy
    };

    try {
      // Send expense data to backend via POST request
      const response = await axios.post('http://localhost:5000/api/expenses', newExpense);

      if (response.status === 201) {
        console.log('Expense added:', response.data.expense);
        setExpenses(prev => [...prev, response.data.expense]);

        // Clear form
        setDescription('');
        setAmount('');
        setPaidBy('');
      }
    } catch (error) {
      console.error('Error adding expense:', error);
    }
  };

  const styles = {
    container: {
      border: '1px solid #ccc',
      padding: '15px',
      borderRadius: '8px',
      marginBottom: '20px'
    },
    heading: {
      fontSize: '18px',
      fontWeight: 'bold',
      marginBottom: '10px'
    },
    input: {
      marginRight: '10px',
      padding: '6px',
      borderRadius: '4px',
      border: '1px solid #ccc'
    },
    button: {
      padding: '6px 12px',
      borderRadius: '4px',
      border: 'none',
      backgroundColor: '#007bff',
      color: 'white',
      cursor: 'pointer'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.heading}>Add Expense</div>
      <input
        type="text"
        placeholder="Description"
        style={styles.input}
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />
      <input
        type="number"
        placeholder="Amount"
        style={styles.input}
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
      />
      <select
        style={styles.input}
        value={paidBy}
        onChange={(e) => setPaidBy(e.target.value)}
      >
        <option value="">Select Payer</option>
        {members.map((member, idx) => (
          <option key={idx} value={member.name}>
            {member.label}
          </option>
        ))}
      </select>
      <button style={styles.button} onClick={handleAddExpense}>
        Add
      </button>
    </div>
  );
};

export default AddExpense;
